const response = $input.item.json;
const content = response.choices[0].message.content;
const webhookData = $('Keep User Details').first().json;
const descriptions = content.split('\n').filter(line => line.trim().startsWith('*')).slice(0, 3);
const propertyData = $('Parse Property Data').first().json;

const imageData = propertyData.images.map((imageUrl, index) => ({
  imageUrl,
  description: descriptions[index] || 'Beautiful property feature with smooth cinematic pan, professional lighting',
  index
}));

return imageData.map(item => ({
  ...propertyData,
  currentImage: item.imageUrl,
  currentDescription: item.description,
  imageIndex: item.index,
  name: webhookData.name,
  email: webhookData.email
}));

const MAX_RETRIES = 20;
const retryCount = $json.retryCount || 0;

if (retryCount >= MAX_RETRIES) {
  throw new Error(`Timeout after ${MAX_RETRIES} retries (15 minutes)`);
}

return {
  taskId: $json.taskId,
  description: $json.description,
  imageUrl: $json.imageUrl,
  address: $json.address,
  price: $json.price,
  beds: $json.beds,
  baths: $json.baths,
  sqft: $json.sqft,
  name: $json.name,
  email: $json.email,
  retryCount: retryCount + 1,
  status: $json.status
};

const videos = items.map((item, index) => ({
  videoUrl: item.json.videoUrl,
  clipNumber: index + 1
}));

const firstItem = items[0].json;

if (videos.length === 0 || !videos[0].videoUrl) {
  throw new Error('No video URLs found');
}

console.log('Final video URLs:', videos.map(v => v.videoUrl));

return {
  success: true,
  property: {
    address: firstItem.address,
    price: firstItem.price,
    beds: firstItem.beds,
    baths: firstItem.baths,
    sqft: firstItem.sqft,
    name: firstItem.name,
    email: firstItem.email
  },
  videos: videos,
  videoCount: videos.length,
  video1Url: videos[0]?.videoUrl || '',
  video2Url: videos[1]?.videoUrl || '',
  video3Url: videos[2]?.videoUrl || '',
  cost: {
    total: videos.length * 0.15,
    perVideo: 0.15
  },
  processingTime: new Date().toISOString()
};

// The Merge node (ID: 4a8ac800) has combined all properties
const inputData = $input.item.json;

// Check if the API call was successful
if (inputData.code !== 200 || !inputData.data || !inputData.data.taskId) {
  throw new Error(`Kie.ai Task Failed. Code: ${inputData.code}, Msg: ${inputData.msg}`);
}

// All properties (from both inputs) are now at the top level
console.log('=== STORE TASK INFO ===');
console.log('Task ID:', inputData.data.taskId);
console.log('Address:', inputData.address); // This will now be correct

return {
  taskId: inputData.data.taskId,
  description: inputData.currentDescription,
  imageUrl: inputData.currentImage,
  address: inputData.address,
  price: inputData.price,
  beds: inputData.beds,
  baths: inputData.baths,
  sqft: inputData.sqft,
  name: inputData.name,
  email: inputData.email,
